import assert from 'node:assert/strict';
import { access, mkdtemp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath, pathToFileURL } from 'node:url';

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');

test('backend build packages the authoritative OpenAPI source into the deployed dist tree', async (t) => {
  const backendPackagePath = path.join(repositoryRoot, 'apps', 'backend', 'package.json');
  const backendPackage = JSON.parse(await readFile(backendPackagePath, 'utf8'));

  assert.match(
    backendPackage.scripts.build,
    /copy-openapi-spec\.mjs/,
    'the backend build must bundle the version-controlled OpenAPI specification',
  );

  const copyScriptPath = path.join(
    repositoryRoot,
    'apps',
    'backend',
    'scripts',
    'copy-openapi-spec.mjs',
  );
  await assert.doesNotReject(
    access(copyScriptPath),
    'the backend OpenAPI packaging helper must exist',
  );

  const { copyOpenApiSpecification } = await import(pathToFileURL(copyScriptPath).href);
  const temporaryRoot = await mkdtemp(path.join(os.tmpdir(), 'sport-analytics-openapi-'));
  t.after(async () => {
    await rm(temporaryRoot, { recursive: true, force: true });
  });

  const sourcePath = path.join(temporaryRoot, 'docs', 'api', 'openapi.yaml');
  await mkdir(path.dirname(sourcePath), { recursive: true });
  const expected = 'openapi: 3.1.0\ninfo:\n  title: Sport Analytics API\n';
  await writeFile(sourcePath, expected, 'utf8');

  const copied = await copyOpenApiSpecification(temporaryRoot);
  assert.equal(copied.sourcePath, sourcePath);
  assert.equal(
    copied.destinationPath,
    path.join(temporaryRoot, 'apps', 'backend', 'dist', 'openapi.yaml'),
  );
  assert.equal(await readFile(copied.destinationPath, 'utf8'), expected);

  const deploymentScript = await readFile(
    path.join(repositoryRoot, 'scripts', 'prepare-backend-deployment.mjs'),
    'utf8',
  );
  assert.match(
    deploymentScript,
    /['"]apps\/backend\/dist['"]/,
    'the Azure deployment artifact must continue to include the complete backend dist directory',
  );
});
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

const ciWorkflow = readFileSync('.gitea/workflows/ci.yml', 'utf8');
const manualFrontendWorkflow = readFileSync('.gitea/workflows/deploy-frontend.yml', 'utf8');

function automaticFrontendJob() {
  const marker = '\n  deploy_frontend:';
  const start = ciWorkflow.indexOf(marker);
  assert.notEqual(start, -1, 'automatic frontend deployment job must exist in CI');
  return ciWorkflow.slice(start);
}

test('automatic frontend deployment waits for quality and only runs for production-impacting frontend changes', () => {
  const job = automaticFrontendJob();

  assert.match(job, /needs:\s*\n\s*- plan\s*\n\s*- quality/);
  assert.match(job, /github\.event_name == 'push'/);
  assert.match(job, /github\.ref == 'refs\/heads\/main'/);
  assert.match(job, /needs\.plan\.outputs\.deployFrontend == 'true'/);
});

test('automatic frontend deployment does not repeat the authoritative frontend unit-test suite', () => {
  const job = automaticFrontendJob();

  assert.doesNotMatch(job, /npm run test:frontend/);
  assert.match(job, /npm run build --workspace=@sport-analytics\/contracts/);
  assert.match(job, /npm run build --workspace=@sport-analytics\/frontend/);
  assert.match(job, /azure\/webapps-deploy@v3/);
  assert.match(job, /smoke-check-deployment\.mjs/);
});

test('standalone frontend deployment workflow is manual recovery only and also avoids duplicate unit tests', () => {
  assert.match(manualFrontendWorkflow, /workflow_dispatch:/);
  assert.doesNotMatch(manualFrontendWorkflow, /\n\s*push:/);
  assert.doesNotMatch(manualFrontendWorkflow, /npm run test:frontend/);
  assert.match(manualFrontendWorkflow, /npm run build --workspace=@sport-analytics\/frontend/);
});

