            { name: 'DATABASE_URL', secretRef: 'database-url' }
            { name: 'OBJECT_STORAGE_PROVIDER', value: 'azure' }
            { name: 'AZURE_STORAGE_ACCOUNT_NAME', value: existingStorage.name }
