import { randomUUID } from 'node:crypto';
import type { AccountDeletionResponse } from '@sport-analytics/contracts';

import type { DeleteAuthUser, VerifiedIdentity } from '../../auth/supabase-auth';
import type { ApplicationAccount } from '../accounts/account';
import { hashAuthenticationSubject } from '../accounts/account-subject';
import {
  AccountDeletionIncompleteError,
  AccountDeletionUnavailableError,
  RecentAuthenticationRequiredError,
} from './account-deletion.errors';
import {
  createAccountDeletionRepository,
  type AccountDeletionRepository,
} from './account-deletion.repository';

const RECENT_AUTHENTICATION_WINDOW_MS = 15 * 60 * 1000;

export interface AccountDeletionService {
  deleteAccount(
    account: ApplicationAccount,
    identity: VerifiedIdentity,
  ): Promise<AccountDeletionResponse>;
}

export function createUnavailableAccountDeletionService(): AccountDeletionService {
  return {
    async deleteAccount() {
      throw new AccountDeletionUnavailableError();
    },
  };
}

function isRecentAuthentication(identity: VerifiedIdentity, now: Date): boolean {
  const lastSignInAt = identity.lastSignInAt;

  if (!lastSignInAt) {
    return false;
  }

  const age = now.getTime() - lastSignInAt.getTime();
  return age >= -60_000 && age <= RECENT_AUTHENTICATION_WINDOW_MS;
}

async function bestEffort(operation: () => Promise<void>): Promise<void> {
  try {
    await operation();
  } catch {
    // The account was disabled by prepare(). A failed status write must not
    // replace the safe public error or cause an unsafe compensating action.
  }
}

export function createAccountDeletionService(
  deleteAuthUser: DeleteAuthUser,
  repository?: AccountDeletionRepository,
  now: () => Date = () => new Date(),
  createTombstoneSubject: () => string = () => `deleted:${randomUUID()}`,
): AccountDeletionService {
  let resolvedRepository = repository;

  function getRepository(): AccountDeletionRepository {
    resolvedRepository ??= createAccountDeletionRepository();
    return resolvedRepository;
  }

  return {
    async deleteAccount(account, identity) {
      if (identity.uid !== account.subject && account.deletionState !== 'deleted') {
        throw new Error('Authenticated identity does not own the application account');
      }

      if (!isRecentAuthentication(identity, now())) {
        throw new RecentAuthenticationRequiredError();
      }

      const accountDeletionRepository = getRepository();
      const prepared = await accountDeletionRepository.prepare(account.accountId);

      if (prepared.state === 'deleted') {
        return {
          data: {
            status: 'deleted',
            retainedCricketData: true,
          },
        };
      }

      if (prepared.state === 'auth_pending') {
        try {
          await deleteAuthUser(prepared.authSubject);
        } catch {
          await bestEffort(() =>
            accountDeletionRepository.markAuthDeletionFailed(account.accountId),
          );
          throw new AccountDeletionIncompleteError();
        }

        try {
          await accountDeletionRepository.markAuthDeleted(account.accountId);
        } catch {
          throw new AccountDeletionIncompleteError();
        }
      }

      try {
        await accountDeletionRepository.finalize(
          account.accountId,
          createTombstoneSubject(),
          hashAuthenticationSubject(prepared.authSubject),
        );
      } catch {
        await bestEffort(() => accountDeletionRepository.markFinalizationFailed(account.accountId));
        throw new AccountDeletionIncompleteError();
      }

      return {
        data: {
          status: 'deleted',
          retainedCricketData: true,
        },
      };
    },
  };
}
import { Router } from 'express';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import type { SynchronizeAccount } from '../accounts/account.service';
import { createAccountDeletionController } from './account-deletion.controller';
import type { AccountDeletionService } from './account-deletion.service';

export function createAccountDeletionRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: AccountDeletionService,
): Router {
  const router = Router();

  router.delete(
    '/account',
    requireAuthentication(verifyAccessToken, synchronizeAccount, {
      allowDisabledAccount: (account) => account.deletionState !== 'active',
    }),
    createAccountDeletionController(service),
  );

  return router;
}
import {
  accountDeletionRequestSchema,
  accountDeletionResponseSchema,
} from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import type { VerifiedIdentity } from '../../auth/supabase-auth';
import type { ApplicationAccount } from '../accounts/account';
import {
  AccountDeletionIncompleteError,
  AccountDeletionUnavailableError,
  RecentAuthenticationRequiredError,
} from './account-deletion.errors';
import type { AccountDeletionService } from './account-deletion.service';

function authenticatedContext(response: Response): {
  account: ApplicationAccount;
  identity: VerifiedIdentity;
} {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;
  const identity = response.locals.authenticatedIdentity as VerifiedIdentity | undefined;

  if (!account || !identity) {
    throw new Error('Account deletion requires an authenticated account and identity');
  }

  return { account, identity };
}

export function createAccountDeletionController(service: AccountDeletionService): RequestHandler {
  return (request, response, next) => {
    const parsed = accountDeletionRequestSchema.safeParse(request.body);

    if (!parsed.success) {
      response.status(422).json({
        error: {
          code: 'DELETION_CONFIRMATION_REQUIRED',
          message: 'Enter DELETE exactly to confirm permanent account deletion.',
        },
      });
      return;
    }

    let context;
    try {
      context = authenticatedContext(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .deleteAccount(context.account, context.identity)
      .then((result) => {
        response.status(200).json(accountDeletionResponseSchema.parse(result));
      })
      .catch((error: unknown) => {
        if (error instanceof AccountDeletionUnavailableError) {
          response.status(501).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        if (error instanceof RecentAuthenticationRequiredError) {
          response.status(403).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        if (error instanceof AccountDeletionIncompleteError) {
          response.status(503).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        next(error);
      });
  };
}

